const input=document.querySelector('#fileInput'),zone=document.querySelector('#dropZone'),preview=document.querySelector('#preview'),browse=document.querySelector('#browseButton'),analyze=document.querySelector('#analyzeButton'),notice=document.querySelector('#notice');
function setFile(file){if(!file||!file.type.startsWith('image/'))return;preview.src=URL.createObjectURL(file);preview.hidden=false;document.querySelector('#emptyState').hidden=true;analyze.disabled=false;notice.textContent='Sketch ready. Analysis will run through the GPU-backed Colab service once it is connected.';}
browse.addEventListener('click',()=>input.click());input.addEventListener('change',()=>setFile(input.files[0]));['dragenter','dragover'].forEach(e=>zone.addEventListener(e,x=>{x.preventDefault();zone.classList.add('drag')}));['dragleave','drop'].forEach(e=>zone.addEventListener(e,x=>{x.preventDefault();zone.classList.remove('drag')}));zone.addEventListener('drop',e=>setFile(e.dataTransfer.files[0]));
analyze.addEventListener('click',()=>{const stages=[...document.querySelectorAll('#stages li')];stages.forEach((s,i)=>{s.classList.toggle('active',i<4);s.querySelector('em').textContent=i===0?'Done':i<4?'Queued':'Blocked';});notice.textContent='A quality gate is required before reconstruction. Connect the Colab backend to run recognition and candidate scoring.';const result=document.querySelector('#resultTemplate').content.cloneNode(true);document.querySelector('main').append(result);analyze.disabled=true;});
